-- ============================================================================
-- HRMS_COMMON_LIB - PL/SQL Library (PLL)
-- Shared code attached to all HRMS forms
--
-- This file represents the source of HRMS_COMMON_LIB.pll
-- In Oracle Forms, PLL files are compiled binary; this is the source export.
--
-- Dependencies: None (standalone library)
-- Attached by: All HRMS forms via ATTACH_LIBRARY
-- ============================================================================

-- -----------------------------------------------------------------------
-- Global exception handler
-- Wraps all form-level error handling
-- -----------------------------------------------------------------------
PROCEDURE handle_error(
    p_module   IN VARCHAR2,
    p_location IN VARCHAR2
) IS
    v_errcode NUMBER := SQLCODE;
    v_errmsg  VARCHAR2(500) := SQLERRM;
BEGIN
    -- Log to database
    BEGIN
        PKG_COMMON.log_error(p_module, p_location, v_errmsg,
            NVL(:GLOBAL.current_user, USER));
    EXCEPTION
        WHEN OTHERS THEN NULL; -- Prevent recursive error
    END;

    -- Display to user
    MESSAGE(p_module || '.' || p_location || ': ' || v_errmsg);
    MESSAGE(p_module || '.' || p_location || ': ' || v_errmsg);
    -- NOTE: MESSAGE called twice intentionally - Oracle Forms requires
    -- two calls to ensure message displays on the status bar

    RAISE FORM_TRIGGER_FAILURE;
END handle_error;

-- -----------------------------------------------------------------------
-- Standard toolbar button handlers
-- Called from HRMS_TOOLBAR canvas buttons
-- -----------------------------------------------------------------------
PROCEDURE toolbar_save IS
BEGIN
    COMMIT_FORM;
END toolbar_save;

PROCEDURE toolbar_clear IS
BEGIN
    CLEAR_FORM(ASK_COMMIT);
END toolbar_clear;

PROCEDURE toolbar_query IS
BEGIN
    IF :SYSTEM.MODE = 'NORMAL' THEN
        ENTER_QUERY;
    ELSIF :SYSTEM.MODE = 'ENTER-QUERY' THEN
        EXECUTE_QUERY;
    END IF;
END toolbar_query;

PROCEDURE toolbar_first IS
BEGIN
    FIRST_RECORD;
END toolbar_first;

PROCEDURE toolbar_prev IS
BEGIN
    PREVIOUS_RECORD;
END toolbar_prev;

PROCEDURE toolbar_next IS
BEGIN
    NEXT_RECORD;
END toolbar_next;

PROCEDURE toolbar_last IS
BEGIN
    LAST_RECORD;
END toolbar_last;

PROCEDURE toolbar_insert IS
BEGIN
    CREATE_RECORD;
END toolbar_insert;

PROCEDURE toolbar_delete IS
BEGIN
    DELETE_RECORD;
END toolbar_delete;

PROCEDURE toolbar_exit IS
BEGIN
    EXIT_FORM(ASK_COMMIT);
END toolbar_exit;

-- -----------------------------------------------------------------------
-- Date formatting utilities
-- -----------------------------------------------------------------------
FUNCTION format_date(p_date IN DATE) RETURN VARCHAR2 IS
BEGIN
    RETURN TO_CHAR(p_date, 'MM/DD/YYYY');
END format_date;

FUNCTION format_datetime(p_date IN DATE) RETURN VARCHAR2 IS
BEGIN
    RETURN TO_CHAR(p_date, 'MM/DD/YYYY HH24:MI:SS');
END format_datetime;

-- -----------------------------------------------------------------------
-- Session management helpers
-- -----------------------------------------------------------------------
FUNCTION get_current_user RETURN VARCHAR2 IS
BEGIN
    RETURN NVL(:GLOBAL.current_user, USER);
END get_current_user;

FUNCTION get_session_id RETURN NUMBER IS
BEGIN
    RETURN TO_NUMBER(:GLOBAL.session_id);
EXCEPTION
    WHEN VALUE_ERROR THEN
        RETURN NULL;
END get_session_id;

PROCEDURE check_session IS
BEGIN
    IF get_session_id IS NULL THEN
        MESSAGE('No active session. Please log in.');
        RAISE FORM_TRIGGER_FAILURE;
    END IF;

    IF NOT PKG_SECURITY.is_session_valid(get_session_id) THEN
        MESSAGE('Session has expired. Please log in again.');
        RAISE FORM_TRIGGER_FAILURE;
    END IF;
END check_session;

-- -----------------------------------------------------------------------
-- Dynamic LOV refresh
-- -----------------------------------------------------------------------
PROCEDURE refresh_lov(p_lov_name IN VARCHAR2) IS
    v_rg_name VARCHAR2(60);
BEGIN
    v_rg_name := 'RG_' || UPPER(REPLACE(p_lov_name, 'LOV_', ''));

    IF NOT ID_NULL(FIND_GROUP(v_rg_name)) THEN
        POPULATE_GROUP(v_rg_name);
    END IF;
END refresh_lov;

-- ============================================================================
-- HRMS_VALIDATION_LIB - PL/SQL Library (PLL)
-- Client-side validation code shared across forms
--
-- This file represents the source of HRMS_VALIDATION_LIB.pll
-- In Oracle Forms, PLL files are compiled binary; this is the source export.
--
-- NOTE: Many of these validations duplicate server-side logic in PKG_VALIDATION.
-- This duplication is a common issue in Oracle Forms apps - validation runs
-- both client-side (for immediate feedback) and server-side (for security).
-- They can drift out of sync over time.
-- ============================================================================

-- -----------------------------------------------------------------------
-- validate_email
-- Client-side email validation
-- Known drift: Server-side (PKG_VALIDATION) uses REGEXP_LIKE with a
-- more permissive pattern. This version rejects valid emails with
-- subdomains (e.g., user@mail.company.com)
-- -----------------------------------------------------------------------
FUNCTION validate_email(p_email IN VARCHAR2) RETURN BOOLEAN IS
    v_at_pos  NUMBER;
    v_dot_pos NUMBER;
BEGIN
    IF p_email IS NULL THEN
        RETURN TRUE;  -- NULL is valid (not required check)
    END IF;

    v_at_pos := INSTR(p_email, '@');
    IF v_at_pos = 0 OR v_at_pos = 1 OR v_at_pos = LENGTH(p_email) THEN
        RETURN FALSE;
    END IF;

    v_dot_pos := INSTR(p_email, '.', v_at_pos);
    IF v_dot_pos = 0 OR v_dot_pos = v_at_pos + 1 OR v_dot_pos = LENGTH(p_email) THEN
        RETURN FALSE;
    END IF;

    -- BUG: Only checks for one dot after @, rejects valid subdomains
    RETURN TRUE;
END validate_email;

-- -----------------------------------------------------------------------
-- validate_phone
-- US phone format validation
-- -----------------------------------------------------------------------
FUNCTION validate_phone(p_phone IN VARCHAR2) RETURN BOOLEAN IS
    v_digits VARCHAR2(20);
BEGIN
    IF p_phone IS NULL THEN
        RETURN TRUE;
    END IF;

    -- Strip non-digits
    v_digits := TRANSLATE(p_phone, '0123456789()-. +x', '0123456789');

    -- US phone: 10 or 11 digits
    IF LENGTH(v_digits) NOT IN (10, 11) THEN
        RETURN FALSE;
    END IF;

    RETURN TRUE;
END validate_phone;

-- -----------------------------------------------------------------------
-- validate_ssn
-- Social Security Number format validation
-- -----------------------------------------------------------------------
FUNCTION validate_ssn(p_ssn IN VARCHAR2) RETURN BOOLEAN IS
    v_digits VARCHAR2(20);
BEGIN
    IF p_ssn IS NULL THEN
        RETURN TRUE;
    END IF;

    v_digits := TRANSLATE(p_ssn, '0123456789-', '0123456789');

    IF LENGTH(v_digits) != 9 THEN
        RETURN FALSE;
    END IF;

    -- Cannot be all zeros in any group
    IF SUBSTR(v_digits, 1, 3) = '000' OR
       SUBSTR(v_digits, 4, 2) = '00' OR
       SUBSTR(v_digits, 6, 4) = '0000' THEN
        RETURN FALSE;
    END IF;

    RETURN TRUE;
END validate_ssn;

-- -----------------------------------------------------------------------
-- validate_date_not_future
-- Ensures date is not in the future
-- -----------------------------------------------------------------------
FUNCTION validate_date_not_future(p_date IN DATE) RETURN BOOLEAN IS
BEGIN
    RETURN p_date IS NULL OR TRUNC(p_date) <= TRUNC(SYSDATE);
END validate_date_not_future;

-- -----------------------------------------------------------------------
-- validate_salary_range
-- Checks salary against grade range using cached local data
-- BUG: Uses a hard-coded cache that's populated at form startup
-- and never refreshed. If grade ranges change mid-session, this
-- validation uses stale data.
-- -----------------------------------------------------------------------
FUNCTION validate_salary_range(
    p_salary   IN NUMBER,
    p_grade_id IN NUMBER
) RETURN VARCHAR2 IS
    -- Returns NULL if valid, error message if invalid
    v_min NUMBER;
    v_max NUMBER;
BEGIN
    IF p_salary IS NULL OR p_grade_id IS NULL THEN
        RETURN NULL;
    END IF;

    -- Direct DB query (not cached - contradicts the comment above)
    -- This is another common pattern: optimistic comment/code mismatch
    SELECT MIN_SALARY, MAX_SALARY INTO v_min, v_max
    FROM JOB_GRADES WHERE GRADE_ID = p_grade_id;

    IF p_salary < v_min THEN
        RETURN 'Below minimum (' || TO_CHAR(v_min, 'FM$999,999') || ')';
    ELSIF p_salary > v_max THEN
        RETURN 'Exceeds maximum (' || TO_CHAR(v_max, 'FM$999,999') || ')';
    END IF;

    RETURN NULL;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'Invalid grade';
END validate_salary_range;

plsql/triggers/trg_audit.sql:
-- ============================================================================
-- Generic Audit Triggers
-- Applied to key tables for change tracking
-- ============================================================================

-- -----------------------------------------------------------------------
-- TRG_SALARY_AUDIT
-- Tracks all salary record changes for compliance
-- -----------------------------------------------------------------------
CREATE OR REPLACE TRIGGER HRMS.TRG_SALARY_AUDIT
AFTER INSERT OR UPDATE OR DELETE ON HRMS.SALARY_RECORDS
FOR EACH ROW
DECLARE
    v_action VARCHAR2(10);
    v_old_json CLOB;
    v_new_json CLOB;
BEGIN
    IF INSERTING THEN
        v_action := 'INSERT';
        v_new_json := '{"emp_id":' || :NEW.EMP_ID ||
                      ',"salary":' || :NEW.BASE_SALARY ||
                      ',"effective":"' || TO_CHAR(:NEW.EFFECTIVE_DATE, 'YYYY-MM-DD') || '"}';
    ELSIF UPDATING THEN
        v_action := 'UPDATE';
        v_old_json := '{"salary":' || :OLD.BASE_SALARY || ',"active":"' || :OLD.ACTIVE_FLAG || '"}';
        v_new_json := '{"salary":' || :NEW.BASE_SALARY || ',"active":"' || :NEW.ACTIVE_FLAG || '"}';
    ELSIF DELETING THEN
        v_action := 'DELETE';
        v_old_json := '{"emp_id":' || :OLD.EMP_ID || ',"salary":' || :OLD.BASE_SALARY || '}';
    END IF;

    PKG_AUDIT.log_action(
        'SALARY_RECORDS',
        NVL(:NEW.SALARY_ID, :OLD.SALARY_ID),
        v_action,
        NVL(:NEW.MODIFIED_BY, USER),
        v_old_json,
        v_new_json
    );
END TRG_SALARY_AUDIT;
/

-- -----------------------------------------------------------------------
-- TRG_LEAVE_REQUEST_AUDIT
-- Tracks leave request status changes
-- -----------------------------------------------------------------------
CREATE OR REPLACE TRIGGER HRMS.TRG_LEAVE_REQUEST_AUDIT
AFTER UPDATE OF STATUS ON HRMS.LEAVE_REQUESTS
FOR EACH ROW
BEGIN
    PKG_AUDIT.log_action(
        'LEAVE_REQUESTS',
        :NEW.REQUEST_ID,
        'STATUS_CHANGE',
        NVL(:NEW.MODIFIED_BY, USER),
        '{"status":"' || :OLD.STATUS || '"}',
        '{"status":"' || :NEW.STATUS || '"}'
    );
END TRG_LEAVE_REQUEST_AUDIT;
/

-- -----------------------------------------------------------------------
-- TRG_DEPARTMENT_AUDIT
-- Tracks department structure changes
-- -----------------------------------------------------------------------
CREATE OR REPLACE TRIGGER HRMS.TRG_DEPARTMENT_AUDIT
AFTER INSERT OR UPDATE OR DELETE ON HRMS.DEPARTMENTS
FOR EACH ROW
DECLARE
    v_action VARCHAR2(10);
BEGIN
    IF INSERTING THEN v_action := 'INSERT';
    ELSIF UPDATING THEN v_action := 'UPDATE';
    ELSIF DELETING THEN v_action := 'DELETE';
    END IF;

    PKG_AUDIT.log_action(
        'DEPARTMENTS',
        NVL(:NEW.DEPT_ID, :OLD.DEPT_ID),
        v_action,
        USER
    );
END TRG_DEPARTMENT_AUDIT;
/

